[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --red: #C41E3A;
      --red-dark: #A01830;
      --red-light: #E8354F;
      --navy: #1B3A5C;
      --navy-dark: #12283F;
      --navy-light: #2A5580;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --warm-bg: #FDF8F6;
      --font-display: 'Space Grotesk', sans-serif;
      --font-body: 'Plus Jakarta Sans', sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      color: var(--gray-800);
      line-height: 1.6;
      background: var(--white);
      overflow-x: hidden;
    }

    /* ── UTILITY ── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

    /* ── HEADER ── */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 100;
      background: rgba(255,255,255,0.97);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow 0.3s ease;
    }
    .header.scrolled { box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
    .header-utility {
      background: var(--navy);
      color: var(--white);
      font-size: 13px;
      padding: 6px 0;
    }
    .header-utility .container {
      display: flex;
      justify-content: flex-end;
      gap: 20px;
    }
    .header-utility a {
      color: rgba(255,255,255,0.85);
      text-decoration: none;
      transition: color 0.2s;
    }
    .header-utility a:hover { color: var(--white); }
    .header-main .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 12px;
      text-decoration: none;
      color: var(--gray-900);
    }
    .logo-icon {
      width: 44px; height: 44px;
      background: var(--red);
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      color: white; font-weight: 800; font-size: 18px;
      font-family: var(--font-display);
    }
    .logo-text {
      font-family: var(--font-display);
      font-size: 20px;
      font-weight: 700;
      line-height: 1.1;
    }
    .logo-text span { display: block; font-size: 11px; font-weight: 500; color: var(--gray-500); letter-spacing: 0.5px; text-transform: uppercase; }
    .nav-desktop { display: flex; align-items: center; gap: 8px; }
    .nav-desktop a {
      text-decoration: none;
      color: var(--gray-600);
      font-size: 15px;
      font-weight: 500;
      padding: 8px 14px;
      border-radius: 8px;
      transition: all 0.2s;
    }
    .nav-desktop a:hover { color: var(--gray-900); background: var(--gray-100); }
    .btn-donate-header {
      background: var(--red);
      color: white;
      font-weight: 600;
      font-size: 15px;
      padding: 10px 24px;
      border-radius: 8px;
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.2s;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }
    .btn-donate-header:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(196,30,58,0.3); }

    .hamburger {
      display: none;
      background: none; border: none; cursor: pointer;
      width: 44px; height: 44px;
      flex-direction: column; align-items: center; justify-content: center; gap: 5px;
    }
    .hamburger span {
      display: block; width: 24px; height: 2px;
      background: var(--gray-700);
      border-radius: 2px;
      transition: all 0.3s;
    }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* ── MOBILE NAV ── */
    .mobile-nav {
      display: none;
      position: fixed; top: 0; left: 0; right: 0; bottom: 0;
      background: var(--white);
      z-index: 99;
      padding-top: 120px;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      opacity: 0;
      transform: translateX(100%);
      transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-nav.open {
      display: flex;
      opacity: 1;
      transform: translateX(0);
    }
    .mobile-nav a {
      text-decoration: none;
      color: var(--gray-700);
      font-size: 20px;
      font-weight: 600;
      padding: 14px 32px;
      border-radius: 12px;
      transition: all 0.2s;
      width: 80%;
      text-align: center;
    }
    .mobile-nav a:hover { background: var(--gray-100); color: var(--red); }
    .mobile-nav .btn-donate-header {
      margin-top: 16px;
      font-size: 18px;
      padding: 14px 40px;
    }

    /* ── HERO ── */
    .hero {
      position: relative;
      min-height: 90vh;
      display: flex;
      align-items: center;
      padding-top: 120px;
      overflow: hidden;
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 40%, #1e4468 70%, var(--navy-dark) 100%);
    }
    .hero::before {
      content: '';
      position: absolute; inset: 0;
      background:
        radial-gradient(ellipse at 20% 50%, rgba(196,30,58,0.15) 0%, transparent 60%),
        radial-gradient(ellipse at 80% 20%, rgba(27,58,92,0.3) 0%, transparent 50%);
    }
    .hero::after {
      content: '';
      position: absolute; inset: 0;
      background: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.03'/%3E%3C/svg%3E");
      opacity: 0.5;
      pointer-events: none;
    }
    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 700px;
      color: var(--white);
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.12);
      backdrop-filter: blur(8px);
      border: 1px solid rgba(255,255,255,0.15);
      color: rgba(255,255,255,0.95);
      font-size: 14px;
      font-weight: 600;
      padding: 8px 16px;
      border-radius: 100px;
      margin-bottom: 24px;
    }
    .hero-badge .pulse {
      width: 8px; height: 8px;
      background: var(--red-light);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(1.5); }
    }
    .hero h1 {
      font-family: var(--font-display);
      font-size: clamp(36px, 5.5vw, 64px);
      font-weight: 700;
      line-height: 1.08;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }
    .hero p {
      font-size: clamp(16px, 2vw, 20px);
      line-height: 1.7;
      color: rgba(255,255,255,0.8);
      margin-bottom: 36px;
      max-width: 580px;
    }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn-primary {
      background: var(--red);
      color: white;
      font-weight: 700;
      font-size: 17px;
      padding: 16px 36px;
      border-radius: 10px;
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.25s;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-body);
    }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(196,30,58,0.4); }
    .btn-secondary {
      background: rgba(255,255,255,0.1);
      backdrop-filter: blur(8px);
      border: 2px solid rgba(255,255,255,0.3);
      color: white;
      font-weight: 600;
      font-size: 17px;
      padding: 14px 32px;
      border-radius: 10px;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.25s;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-body);
    }
    .btn-secondary:hover { background: rgba(255,255,255,0.2); border-color: rgba(255,255,255,0.5); }
    .hero-image-area {
      position: absolute;
      right: -40px; bottom: 0; top: 0;
      width: 45%;
      display: flex; align-items: flex-end;
    }
    .hero-image-placeholder {
      width: 100%; height: 80%;
      background: linear-gradient(135deg, rgba(255,255,255,0.05) 0%, rgba(255,255,255,0.02) 100%);
      border-radius: 20px 0 0 0;
      display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,0.15);
      font-size: 14px;
      text-align: center;
      padding: 20px;
    }

    /* ── MISSION ── */
    .mission {
      padding: 100px 0;
      background: var(--white);
    }
    .mission-inner {
      display: grid;
      grid-template-columns: 1fr 1.3fr;
      gap: 60px;
      align-items: center;
    }
    .mission-label {
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--red);
      margin-bottom: 16px;
    }
    .mission h2 {
      font-family: var(--font-display);
      font-size: clamp(28px, 3.5vw, 42px);
      font-weight: 700;
      color: var(--gray-900);
      line-height: 1.15;
      margin-bottom: 24px;
      letter-spacing: -0.01em;
    }
    .mission-text {
      font-size: 17px;
      line-height: 1.8;
      color: var(--gray-600);
    }
    .mission-image {
      background: var(--gray-100);
      border-radius: 16px;
      height: 400px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 14px;
      overflow: hidden;
      position: relative;
    }
    .mission-image::after {
      content: '';
      position: absolute;
      inset: 0;
      border: 1px solid var(--gray-200);
      border-radius: 16px;
    }

    /* ── IMPACT STATS ── */
    .impact {
      padding: 80px 0;
      background: var(--navy);
      position: relative;
      overflow: hidden;
    }
    .impact::before {
      content: '';
      position: absolute;
      top: -50%; left: -20%;
      width: 60%; height: 200%;
      background: radial-gradient(ellipse, rgba(196,30,58,0.1) 0%, transparent 70%);
    }
    .impact .container { position: relative; z-index: 1; }
    .impact-heading {
      text-align: center;
      margin-bottom: 60px;
    }
    .impact-heading h2 {
      font-family: var(--font-display);
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 700;
      color: var(--white);
      margin-bottom: 12px;
    }
    .impact-heading p {
      font-size: 17px;
      color: rgba(255,255,255,0.6);
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }
    .stat-card {
      text-align: center;
      padding: 40px 24px;
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 16px;
      transition: all 0.3s;
    }
    .stat-card:hover {
      background: rgba(255,255,255,0.08);
      transform: translateY(-4px);
      border-color: rgba(196,30,58,0.3);
    }
    .stat-number {
      font-family: var(--font-display);
      font-size: clamp(36px, 4vw, 52px);
      font-weight: 700;
      color: var(--white);
      line-height: 1;
      margin-bottom: 8px;
    }
    .stat-suffix {
      font-size: clamp(20px, 2.5vw, 28px);
      color: var(--red-light);
    }
    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.6);
      font-weight: 500;
    }
    .impact-footnote {
      text-align: center;
      margin-top: 48px;
      font-size: 15px;
      color: rgba(255,255,255,0.45);
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
    }

    /* ── PROGRAMS ── */
    .programs {
      padding: 100px 0;
      background: var(--gray-50);
    }
    .section-header {
      text-align: center;
      margin-bottom: 56px;
    }
    .section-label {
      font-family: var(--font-display);
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 2px;
      color: var(--red);
      margin-bottom: 12px;
    }
    .section-title {
      font-family: var(--font-display);
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 700;
      color: var(--gray-900);
      line-height: 1.15;
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 17px;
      color: var(--gray-500);
      max-width: 550px;
      margin: 0 auto;
    }
    .accordion-list { max-width: 800px; margin: 0 auto; }
    .accordion-item {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 12px;
      margin-bottom: 12px;
      overflow: hidden;
      transition: all 0.3s;
    }
    .accordion-item:hover { border-color: var(--gray-300); }
    .accordion-item.active { border-color: var(--red); box-shadow: 0 4px 16px rgba(196,30,58,0.08); }
    .accordion-trigger {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 20px 24px;
      background: none;
      border: none;
      cursor: pointer;
      text-align: left;
      font-family: var(--font-body);
      transition: all 0.2s;
    }
    .accordion-trigger:hover { background: var(--gray-50); }
    .accordion-trigger-left {
      display: flex;
      align-items: center;
      gap: 16px;
    }
    .accordion-icon {
      width: 44px; height: 44px;
      background: var(--warm-bg);
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
      font-size: 20px;
    }
    .accordion-item.active .accordion-icon { background: var(--red); }
    .accordion-item.active .accordion-icon svg { color: white; }
    .accordion-trigger h3 {
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 600;
      color: var(--gray-800);
    }
    .accordion-chevron {
      width: 24px; height: 24px;
      transition: transform 0.3s ease;
      color: var(--gray-400);
      flex-shrink: 0;
    }
    .accordion-item.active .accordion-chevron { transform: rotate(180deg); color: var(--red); }
    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .accordion-content-inner {
      padding: 0 24px 24px;
      padding-left: 84px;
      font-size: 16px;
      line-height: 1.7;
      color: var(--gray-600);
    }

    /* ── GET INVOLVED ── */
    .get-involved {
      padding: 100px 0;
      background: var(--white);
    }
    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }
    .involved-card {
      padding: 40px 32px;
      border: 1px solid var(--gray-200);
      border-radius: 16px;
      transition: all 0.3s;
      position: relative;
      overflow: hidden;
    }
    .involved-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 4px;
      background: var(--red);
      transform: scaleX(0);
      transition: transform 0.3s;
    }
    .involved-card:hover { border-color: var(--red); transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); }
    .involved-card:hover::before { transform: scaleX(1); }
    .involved-card-icon {
      width: 56px; height: 56px;
      background: var(--warm-bg);
      border-radius: 14px;
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 24px;
      font-size: 24px;
    }
    .involved-card h3 {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 700;
      color: var(--gray-900);
      margin-bottom: 12px;
    }
    .involved-card p {
      font-size: 15px;
      line-height: 1.7;
      color: var(--gray-500);
      margin-bottom: 24px;
    }
    .btn-outline {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 20px;
      border: 2px solid var(--red);
      color: var(--red);
      font-weight: 600;
      font-size: 15px;
      border-radius: 8px;
      text-decoration: none;
      cursor: pointer;
      background: none;
      transition: all 0.2s;
      font-family: var(--font-body);
    }
    .btn-outline:hover { background: var(--red); color: white; }

    /* ── NEWS ── */
    .news {
      padding: 100px 0;
      background: var(--gray-50);
    }
    .news-carousel-wrapper {
      position: relative;
      overflow: hidden;
    }
    .news-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .news-card {
      min-width: calc(33.333% - 16px);
      background: var(--white);
      border-radius: 16px;
      border: 1px solid var(--gray-200);
      overflow: hidden;
      transition: all 0.3s;
      flex-shrink: 0;
    }
    .news-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); border-color: var(--gray-300); }
    .news-card-image {
      height: 200px;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 13px;
      position: relative;
      overflow: hidden;
    }
    .news-card-image .news-category {
      position: absolute;
      top: 16px;
      left: 16px;
      background: var(--red);
      color: white;
      font-size: 12px;
      font-weight: 600;
      padding: 4px 12px;
      border-radius: 100px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .news-card-body { padding: 24px; }
    .news-card-body h3 {
      font-family: var(--font-display);
      font-size: 18px;
      font-weight: 700;
      color: var(--gray-900);
      margin-bottom: 10px;
      line-height: 1.3;
    }
    .news-card-body p {
      font-size: 14px;
      line-height: 1.7;
      color: var(--gray-500);
      margin-bottom: 16px;
    }
    .news-card-body a {
      color: var(--red);
      font-weight: 600;
      font-size: 14px;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 4px;
      transition: gap 0.2s;
    }
    .news-card-body a:hover { gap: 8px; }
    .carousel-controls {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 40px;
    }
    .carousel-btn {
      width: 48px; height: 48px;
      border-radius: 50%;
      border: 2px solid var(--gray-300);
      background: var(--white);
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      transition: all 0.2s;
      color: var(--gray-600);
    }
    .carousel-btn:hover { border-color: var(--red); color: var(--red); background: var(--warm-bg); }
    .carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
    .carousel-btn:disabled:hover { border-color: var(--gray-300); color: var(--gray-600); background: var(--white); }
    .carousel-dots {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .carousel-dot {
      width: 10px; height: 10px;
      border-radius: 50%;
      background: var(--gray-300);
      border: none;
      cursor: pointer;
      transition: all 0.2s;
      padding: 0;
    }
    .carousel-dot.active { background: var(--red); width: 28px; border-radius: 5px; }

    /* ── DONATE CTA ── */
    .donate-cta {
      padding: 100px 0;
      background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
      position: relative;
      overflow: hidden;
    }
    .donate-cta::before {
      content: '';
      position: absolute; inset: 0;
      background:
        radial-gradient(ellipse at 30% 0%, rgba(255,255,255,0.1) 0%, transparent 50%),
        radial-gradient(ellipse at 70% 100%, rgba(0,0,0,0.15) 0%, transparent 50%);
    }
    .donate-cta .container { position: relative; z-index: 1; text-align: center; }
    .donate-cta h2 {
      font-family: var(--font-display);
      font-size: clamp(32px, 4vw, 48px);
      font-weight: 700;
      color: var(--white);
      margin-bottom: 16px;
    }
    .donate-cta > .container > p {
      font-size: 18px;
      color: rgba(255,255,255,0.85);
      max-width: 600px;
      margin: 0 auto 24px;
      line-height: 1.7;
    }
    .donate-efficiency {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      padding: 10px 20px;
      border-radius: 100px;
      color: var(--white);
      font-weight: 600;
      font-size: 15px;
      margin-bottom: 40px;
    }
    .donate-amounts {
      display: flex;
      justify-content: center;
      gap: 16px;
      margin-bottom: 32px;
      flex-wrap: wrap;
    }
    .donate-amount-card {
      background: rgba(255,255,255,0.12);
      border: 2px solid rgba(255,255,255,0.25);
      border-radius: 14px;
      padding: 24px 28px;
      text-align: center;
      color: white;
      cursor: pointer;
      transition: all 0.25s;
      min-width: 160px;
    }
    .donate-amount-card:hover, .donate-amount-card.selected {
      background: rgba(255,255,255,0.2);
      border-color: var(--white);
      transform: translateY(-2px);
    }
    .donate-amount-card .amount {
      font-family: var(--font-display);
      font-size: 28px;
      font-weight: 700;
      margin-bottom: 6px;
    }
    .donate-amount-card .impact-desc {
      font-size: 13px;
      color: rgba(255,255,255,0.8);
      line-height: 1.4;
    }
    .btn-donate-cta {
      background: var(--white);
      color: var(--red);
      font-weight: 700;
      font-size: 18px;
      padding: 18px 48px;
      border-radius: 12px;
      border: none;
      cursor: pointer;
      transition: all 0.25s;
      font-family: var(--font-body);
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }
    .btn-donate-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }

    /* ── FOOTER ── */
    .footer {
      background: var(--gray-900);
      padding: 64px 0 0;
      color: rgba(255,255,255,0.6);
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 40px;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .footer-brand .logo-text { color: white; margin-bottom: 16px; }
    .footer-brand .logo-text span { color: rgba(255,255,255,0.5); }
    .footer-brand p { font-size: 14px; line-height: 1.7; margin-bottom: 20px; }
    .social-links { display: flex; gap: 10px; }
    .social-link {
      width: 40px; height: 40px;
      border-radius: 10px;
      background: rgba(255,255,255,0.08);
      display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,0.5);
      text-decoration: none;
      font-size: 13px;
      font-weight: 600;
      transition: all 0.2s;
    }
    .social-link:hover { background: var(--red); color: white; }
    .footer-col h4 {
      font-family: var(--font-display);
      font-size: 14px;
      font-weight: 700;
      color: var(--white);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 20px;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a {
      color: rgba(255,255,255,0.5);
      text-decoration: none;
      font-size: 14px;
      transition: all 0.2s;
    }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom {
      padding: 24px 0;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 13px;
      flex-wrap: wrap;
      gap: 12px;
    }

    /* ── DONATE MODAL ── */
    .modal-overlay {
      position: fixed; inset: 0;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
      z-index: 200;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      transition: opacity 0.3s;
    }
    .modal-overlay.open { display: flex; opacity: 1; }
    .modal {
      background: var(--white);
      border-radius: 20px;
      max-width: 540px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      transform: translateY(20px);
      transition: transform 0.3s;
      box-shadow: 0 24px 64px rgba(0,0,0,0.2);
    }
    .modal-overlay.open .modal { transform: translateY(0); }
    .modal-header {
      padding: 28px 28px 0;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
    }
    .modal-header h2 {
      font-family: var(--font-display);
      font-size: 26px;
      font-weight: 700;
      color: var(--gray-900);
    }
    .modal-header p {
      font-size: 15px;
      color: var(--gray-500);
      margin-top: 6px;
    }
    .modal-close {
      width: 40px; height: 40px;
      border-radius: 10px;
      border: 1px solid var(--gray-200);
      background: var(--white);
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      color: var(--gray-500);
      transition: all 0.2s;
      flex-shrink: 0;
    }
    .modal-close:hover { background: var(--gray-100); color: var(--gray-700); }
    .modal-body { padding: 24px 28px 28px; }
    .modal-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 16px;
    }
    .modal-amount-btn {
      padding: 14px 8px;
      border: 2px solid var(--gray-200);
      border-radius: 10px;
      background: var(--white);
      cursor: pointer;
      text-align: center;
      transition: all 0.2s;
      font-family: var(--font-body);
    }
    .modal-amount-btn:hover { border-color: var(--red); }
    .modal-amount-btn.selected { border-color: var(--red); background: var(--warm-bg); }
    .modal-amount-btn .amt {
      font-family: var(--font-display);
      font-size: 22px;
      font-weight: 700;
      color: var(--gray-900);
      display: block;
    }
    .modal-amount-btn .desc {
      font-size: 12px;
      color: var(--gray-500);
      margin-top: 4px;
      display: block;
      line-height: 1.3;
    }
    .modal-custom {
      margin-bottom: 20px;
    }
    .modal-custom label {
      display: block;
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-700);
      margin-bottom: 6px;
    }
    .modal-custom-input {
      display: flex;
      align-items: center;
      border: 2px solid var(--gray-200);
      border-radius: 10px;
      overflow: hidden;
      transition: border-color 0.2s;
    }
    .modal-custom-input:focus-within { border-color: var(--red); }
    .modal-custom-input span {
      padding: 12px 14px;
      background: var(--gray-50);
      font-weight: 700;
      color: var(--gray-500);
      font-size: 18px;
    }
    .modal-custom-input input {
      width: 100%;
      padding: 12px;
      border: none;
      outline: none;
      font-size: 18px;
      font-family: var(--font-body);
      color: var(--gray-900);
    }
    .modal-frequency {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }
    .freq-btn {
      flex: 1;
      padding: 10px;
      border: 2px solid var(--gray-200);
      border-radius: 8px;
      background: var(--white);
      cursor: pointer;
      font-weight: 600;
      font-size: 14px;
      color: var(--gray-600);
      transition: all 0.2s;
      font-family: var(--font-body);
      text-align: center;
    }
    .freq-btn:hover { border-color: var(--red); }
    .freq-btn.selected { border-color: var(--red); background: var(--warm-bg); color: var(--red); }
    .btn-modal-donate {
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: white;
      font-weight: 700;
      font-size: 17px;
      border: none;
      border-radius: 10px;
      cursor: pointer;
      transition: all 0.2s;
      font-family: var(--font-body);
    }
    .btn-modal-donate:hover { background: var(--red-dark); }
    .modal-secure {
      text-align: center;
      margin-top: 12px;
      font-size: 13px;
      color: var(--gray-400);
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
    }

    /* ── ANIMATIONS ── */
    .fade-in {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 0.7s ease, transform 0.7s ease;
    }
    .fade-in.visible {
      opacity: 1;
      transform: translateY(0);
    }
    .fade-in-delay-1 { transition-delay: 0.1s; }
    .fade-in-delay-2 { transition-delay: 0.2s; }
    .fade-in-delay-3 { transition-delay: 0.3s; }

    /* ── RESPONSIVE ── */
    @media (max-width: 1024px) {
      .nav-desktop { display: none; }
      .hamburger { display: flex; }
      .hero-image-area { display: none; }
      .hero-content { max-width: 100%; }
      .mission-inner { grid-template-columns: 1fr; gap: 40px; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
      .involved-grid { grid-template-columns: 1fr; max-width: 500px; margin: 0 auto; }
      .news-card { min-width: calc(50% - 12px); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 768px) {
      .header-utility { display: none; }
      .hero { min-height: 80vh; padding-top: 100px; }
      .hero h1 { font-size: 32px; }
      .hero p { font-size: 16px; }
      .hero-actions { flex-direction: column; }
      .hero-actions .btn-primary,
      .hero-actions .btn-secondary { width: 100%; justify-content: center; }
      .mission, .programs, .get-involved, .news, .donate-cta { padding: 64px 0; }
      .stat-card { padding: 24px 16px; }
      .stat-number { font-size: 32px; }
      .news-card { min-width: 100%; }
      .donate-amounts { flex-direction: column; align-items: center; }
      .donate-amount-card { width: 100%; max-width: 300px; }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; text-align: center; }
      .modal-amounts { grid-template-columns: repeat(2, 1fr); }
      .accordion-content-inner { padding-left: 24px; }
    }

    @media (max-width: 480px) {
      .hero { min-height: 70vh; }
      .hero h1 { font-size: 28px; }
      .stats-grid { grid-template-columns: 1fr 1fr; gap: 12px; }
      .stat-number { font-size: 28px; }
      .section-title { font-size: 24px; }
    }
  </style>
</head>
<body>

  <!-- HEADER -->
  <header class="header" id="header">
    <div class="header-utility">
      <div class="container">
