      </div>
    </div>
    <div class="hero-image-area" aria-hidden="true">
      <div class="hero-image-placeholder">
        <span>Relief workers providing aid to disaster-affected communities</span>
      </div>
    </div>
  </section>

  <!-- MISSION -->
  <section class="mission" id="mission" aria-label="Our mission">
    <div class="container">
      <div class="mission-inner">
        <div class="fade-in">
          <div class="mission-label">Our Mission</div>
          <h2>Preventing and Alleviating Human Suffering</h2>
          <p class="mission-text">
            Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.
          </p>
          <p class="mission-text" style="margin-top: 16px;">
            We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most — regardless of race, religion, nationality, or political affiliation.
          </p>
        </div>
        <div class="mission-image fade-in fade-in-delay-1" role="img" aria-label="Diverse community members and aid workers collaborating during disaster recovery">
          <span>Diverse community members and aid workers collaborating during recovery</span>
        </div>
      </div>
    </div>
  </section>

