  <script>
    // ── HEADER SCROLL EFFECT ──
    let lastScroll = 0;
    window.addEventListener('scroll', () => {
      const header = document.getElementById('header');
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    // ── MOBILE MENU ──
    const hamburger = document.getElementById('hamburgerBtn');
    const mobileNav = document.getElementById('mobileNav');

    hamburger.addEventListener('click', () => {
      const isOpen = mobileNav.classList.contains('open');
      if (isOpen) {
        closeMobileNav();
      } else {
        mobileNav.classList.add('open');
        hamburger.classList.add('active');
        hamburger.setAttribute('aria-expanded', 'true');
        document.body.style.overflow = 'hidden';
      }
    });

    function closeMobileNav() {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
    }

    // ── ACCORDION ──
    document.querySelectorAll('.accordion-trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const item = trigger.closest('.accordion-item');
        const content = item.querySelector('.accordion-content');
        const inner = item.querySelector('.accordion-content-inner');
        const isActive = item.classList.contains('active');

        document.querySelectorAll('.accordion-item').forEach(other => {
          other.classList.remove('active');
          other.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
          other.querySelector('.accordion-content').style.maxHeight = '0';
        });

        if (!isActive) {
          item.classList.add('active');
          trigger.setAttribute('aria-expanded', 'true');
          content.style.maxHeight = inner.scrollHeight + 24 + 'px';
        }
      });
    });

    // ── NEWS CAROUSEL ──
    const newsTrack = document.getElementById('newsTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    const dots = document.querySelectorAll('.carousel-dot');
    let carouselIndex = 0;

    function getVisibleCards() {
      const w = window.innerWidth;
      if (w <= 768) return 1;
      if (w <= 1024) return 2;
      return 3;
    }

    function getMaxIndex() {
      return Math.max(0, 4 - getVisibleCards());
    }

    function updateCarousel() {
      const visible = getVisibleCards();
      const cardWidth = newsTrack.children[0].offsetWidth + 24;
      newsTrack.style.transform = `translateX(-${carouselIndex * cardWidth}px)`;

      prevBtn.disabled = carouselIndex === 0;
      nextBtn.disabled = carouselIndex >= getMaxIndex();

      dots.forEach((d, i) => {
        const isActive = i === carouselIndex;
        d.classList.toggle('active', isActive);
        d.setAttribute('aria-selected', isActive ? 'true' : 'false');
      });
    }

    prevBtn.addEventListener('click', () => {
      if (carouselIndex > 0) {
        carouselIndex--;
        updateCarousel();
      }
    });

    nextBtn.addEventListener('click', () => {
      if (carouselIndex < getMaxIndex()) {
        carouselIndex++;
        updateCarousel();
      }
    });

    dots.forEach(dot => {
      dot.addEventListener('click', () => {
        carouselIndex = parseInt(dot.dataset.index);
        if (carouselIndex > getMaxIndex()) carouselIndex = getMaxIndex();
        updateCarousel();
      });
    });

    window.addEventListener('resize', () => {
      if (carouselIndex > getMaxIndex()) carouselIndex = getMaxIndex();
      updateCarousel();
    });

    // ── DONATE MODAL ──
    let selectedAmount = 100;
    let selectedFrequency = 'once';

    function openDonateModal() {
      const modal = document.getElementById('donateModal');
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      modal.querySelector('.modal-close').focus();
    }

    function closeDonateModal() {
      const modal = document.getElementById('donateModal');
      modal.classList.remove('open');
      document.body.style.overflow = '';
    }

    document.getElementById('donateModal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) closeDonateModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeDonateModal();
    });

    function selectModalAmount(btn, amount) {
      document.querySelectorAll('.modal-amount-btn').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      selectedAmount = amount;
      document.getElementById('customAmount').value = '';
      updateDonateButton();
    }

    function handleCustomAmount() {
      const val = document.getElementById('customAmount').value;
      if (val && parseInt(val) > 0) {
        document.querySelectorAll('.modal-amount-btn').forEach(b => b.classList.remove('selected'));
        selectedAmount = parseInt(val);
        updateDonateButton();
      }
    }

    function selectFrequency(btn, freq) {
      document.querySelectorAll('.freq-btn').forEach(b => {
        b.classList.remove('selected');
        b.setAttribute('aria-checked', 'false');
      });
      btn.classList.add('selected');
      btn.setAttribute('aria-checked', 'true');
      selectedFrequency = freq;
      updateDonateButton();
    }

    function updateDonateButton() {
      const btn = document.getElementById('modalDonateBtn');
      const freqLabel = selectedFrequency === 'once' ? '' : selectedFrequency === 'monthly' ? '/month' : '/year';
      btn.textContent = `Donate $${selectedAmount.toLocaleString()}${freqLabel}`;
    }

    function submitDonation() {
      const btn = document.getElementById('modalDonateBtn');
      btn.textContent = 'Thank you for your generosity!';
      btn.style.background = '#16a34a';
      setTimeout(() => {
        closeDonateModal();
        btn.style.background = '';
        updateDonateButton();
      }, 2000);
    }

    function selectDonateAmount(card, amount) {
      document.querySelectorAll('.donate-amount-card').forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      selectedAmount = amount;
    }

    // ── ANIMATED COUNTERS ──
    function animateCounters() {
      document.querySelectorAll('.stat-number').forEach(el => {
        const target = parseInt(el.dataset.target);
        const suffix = el.dataset.suffix || '';
        const prefix = el.dataset.prefix || '';
        const duration = 2000;
        const start = performance.now();

        function update(time) {
          const elapsed = time - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.round(target * eased);

          el.textContent = prefix + current.toLocaleString() + suffix;

          if (progress < 1) requestAnimationFrame(update);
        }

        requestAnimationFrame(update);
      });
    }

    // ── SCROLL ANIMATIONS ──
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');

          if (entry.target.closest('.impact') && entry.target.classList.contains('stat-card')) {
            const allStats = document.querySelectorAll('.stat-card');
            const allVisible = Array.from(allStats).every(s => s.classList.contains('visible'));
            if (allVisible) animateCounters();
          }

          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

